@php($variant = $product->variants->first())
<article class="product-card"><div class="product-card__media"><a href="{{ route('products.show', $product) }}"><img src="{{ $product->image_url }}" alt="{{ $product->name }}" loading="lazy"></a>@if(auth()->check())<form method="post" action="{{ route('wishlist.toggle', $product) }}" class="product-card__favorite-form">@csrf<button class="product-card__favorite" type="submit" aria-label="Save {{ $product->name }}">@include('components.icon', ['name'=>'heart'])</button></form>@else<a class="product-card__favorite" href="{{ route('login') }}" aria-label="Sign in to save {{ $product->name }}">@include('components.icon', ['name'=>'heart'])</a>@endif</div><a href="{{ route('products.show', $product) }}"><h3>{{ $product->name }}</h3></a><div class="price"><strong>${{ number_format($product->price, 2) }}</strong>@if($product->compare_at_price)<span class="compare">${{ number_format($product->compare_at_price, 2) }}</span>@endif</div><div class="rating" aria-label="{{ $product->rating }} out of 5 stars">{{ str_repeat('★', (int) round($product->rating)) }}{{ str_repeat('☆', 5 - (int) round($product->rating)) }} <span>({{ $product->review_count }})</span></div>@if($variant)<form method="post" action="{{ route('cart.store') }}">@csrf<input type="hidden" name="variant_id" value="{{ $variant->id }}"><button class="card-cart" type="submit">@include('components.icon', ['name'=>'cart']) &nbsp; Add to Cart</button></form>@endif</article>
